const MAX_LOGIN_ATTEMPTS = 5
const LOCKOUT_DURATION_MS = 15 * 60 * 1000
const MAX_LEDGER_ENTRIES = 20_000
const UNLOCKED_RETENTION_MS = 30 * 24 * 60 * 60 * 1000

type LedgerEntry = { count: number; lockedUntil: number; lastFailedAt: number }
const loginAttempts = new Map<string, LedgerEntry>()

// unchanged lockout semantics
function isLockedOut(identifier: string): boolean {
  const entry = loginAttempts.get(identifier)
  if (!entry) return false
  if (Date.now() > entry.lockedUntil) {
    loginAttempts.delete(identifier)
    return false
  }
  return true
}

// Owner-side eviction, amortized: runs only past the aggregate cap, oldest keys first
// (Map preserves insertion order). Active locks are never evicted; expired-locked rows
// delete exactly as the current touch-time behavior in isLockedOut.
function sweepLoginAttempts(now: number) {
  if (loginAttempts.size <= MAX_LEDGER_ENTRIES) return
  for (const [id, entry] of loginAttempts) {
    if (now <= entry.lockedUntil) continue
    if (entry.lockedUntil !== 0 || now - entry.lastFailedAt > UNLOCKED_RETENTION_MS) {
      loginAttempts.delete(id)
    }
    if (loginAttempts.size <= MAX_LEDGER_ENTRIES) break
  }
}

function recordFailedAttempt(identifier: string) {
  const entry = loginAttempts.get(identifier) ?? { count: 0, lockedUntil: 0, lastFailedAt: Date.now() }
  entry.count++
  entry.lastFailedAt = Date.now()
  if (entry.count >= MAX_LOGIN_ATTEMPTS) {
    entry.lockedUntil = Date.now() + LOCKOUT_DURATION_MS
  }
  loginAttempts.set(identifier, entry)
}

function clearAttempts(identifier: string) {
  loginAttempts.delete(identifier)
}

// in CredentialsProvider.authorize, after checkRateLimit passes:
//   sweepLoginAttempts(Date.now())

function isLockedOut(identifier: string): boolean {
  const entry = loginAttempts.get(identifier)
  if (!entry) return false
  // Only entries where a real lock was posted (lockedUntil > 0) are time-bound;
  // the countable sentinel { count >= 1, lockedUntil: 0 } must survive
  // sequential reads until MAX_LOGIN_ATTEMPTS is reached.
  if (entry.lockedUntil > 0 && Date.now() > entry.lockedUntil) {
    loginAttempts.delete(identifier)
    return false
  }
  return entry.lockedUntil > 0
}

const WINDOW_MS = 60_000
const MAX_REQUESTS = 10
const MAX_KEYS = 10_000
const MAX_KEY_LENGTH = 64
const OVERFLOW_KEY = "\u0000overflow"

const ipRequestCounts = new Map<string, { count: number; resetAt: number }>()

/** Single key derivation shared by EVERY consumer.*/
export function normalizeIpKey(raw: string | null | undefined): string {
  if (!raw) return "unknown"
  const first = raw.split(",")[0]!.trim().slice(0, MAX_KEY_LENGTH)
  return /^[0-9a-fA-F.:[\]]+$/.test(first) ? first : "unknown"
}

function evictExpired(now: number) {
  if (ipRequestCounts.size < MAX_KEYS) return
  for (const [key, entry] of ipRequestCounts) {
    if (now > entry.resetAt) ipRequestCounts.delete(key)
    if (ipRequestCounts.size < MAX_KEYS) return
  }
}

export function checkRateLimit(ip: string): { allowed: boolean; remaining: number; resetAt: number } {
  const now = Date.now()
  evictExpired(now)
  if (ip !== OVERFLOW_KEY && !ipRequestCounts.has(ip) && ipRequestCounts.size >= MAX_KEYS) {
    // at capacity with a novel key: park caller into one coarse shared bucket
    return checkRateLimit(OVERFLOW_KEY)
  }
  const entry = ipRequestCounts.get(ip)
  if (!entry || now > entry.resetAt) {
    const resetAt = now + WINDOW_MS
    ipRequestCounts.set(ip, { count: 1, resetAt })
    return { allowed: true, remaining: MAX_REQUESTS - 1, resetAt }
  }
  if (entry.count < Number.MAX_SAFE_INTEGER) entry.count++
  if (entry.count > MAX_REQUESTS) {
    return { allowed: false, remaining: 0, resetAt: entry.resetAt }
  }
  return { allowed: true, remaining: MAX_REQUESTS - entry.count, resetAt: entry.resetAt }
}

